<template><section class="mx-auto max-w-2xl"><h1 class="text-3xl font-black">Checkout</h1><div class="mt-7 rounded-2xl border bg-white p-6"><label class="font-bold">Shipping address</label><textarea v-model="address" required rows="4" class="mt-2 w-full rounded-xl border p-3"></textarea><label class="mt-5 block font-bold">Affiliate code <span class="font-normal text-slate-400">(optional)</span></label><input v-model="affiliateCode" class="mt-2 w-full rounded-xl border p-3"/><p v-if="error" class="mt-3 text-red-600">{{error}}</p><div class="mt-6 flex justify-between border-t pt-5 font-black"><span>Total</span><span>{{cartTotal.toLocaleString()}} ETB</span></div><button :disabled="busy" @click="submit" class="mt-5 w-full rounded-xl bg-indigo-600 py-3 font-bold text-white disabled:opacity-50">{{busy?'Placing order…':'Place order'}}</button></div></section></template><script>import api from'../services/api';import{cart,cartTotal,clearCart}from'../stores';export default{data(){return{address:'',affiliateCode:'',error:'',busy:false,cartTotal}},async mounted(){for(const i of cart.items){try{await api.post('/cart/items',{productId:i.productId,variantId:i.variantId,quantity:i.quantity})}catch(e){this.error=e.response?.data?.message||'Unable to prepare your cart';return}}},methods:{async submit(){this.busy=true;try{await api.post('/orders',{affiliateCode:this.affiliateCode||undefined,shippingAddress:{address:this.address}});clearCart();this.$router.push('/orders')}catch(e){this.error=e.response?.data?.message||'Unable to place order'}finally{this.busy=false}}}}</script>